@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-background-secondary: var(--background-secondary);
  --color-surface: var(--surface);
  --color-surface-elevated: var(--surface-elevated);
  --color-success: var(--success);
  --color-primary-hover: var(--primary-hover);
  --font-sans: var(--font-sans);
  --font-mono: var(--font-geist-mono);
  --font-heading: var(--font-sans);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
  --color-ring: var(--ring);
  --color-input: var(--input);
  --color-border: var(--border);
  --color-destructive: var(--destructive);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent: var(--accent);
  --color-muted-foreground: var(--muted-foreground);
  --color-muted: var(--muted);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-secondary: var(--secondary);
  --color-primary-foreground: var(--primary-foreground);
  --color-primary: var(--primary);
  --color-popover-foreground: var(--popover-foreground);
  --color-popover: var(--popover);
  --color-card-foreground: var(--card-foreground);
  --color-card: var(--card);
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);

  --animate-float: float 5s ease-in-out infinite alternate;
}

:root {
  /* Instagram Official Token System (derived directly from the approved Home button) */
  --instagram-accent: #E1306C;
  --instagram-accent-soft: #FFF0F5;
  --instagram-gradient: linear-gradient(90deg, #833AB4 0%, #C13584 26%, #E1306C 50%, #F56040 74%, #FCAF45 100%);
  --instagram-gradient-border: linear-gradient(135deg, #833AB4 0%, #C13584 28%, #E1306C 52%, #F56040 76%, #FCAF45 100%);
  --instagram-gradient-hover: linear-gradient(90deg, #7734A4 0%, #B83279 26%, #D82D66 50%, #EA593C 74%, #F2A63F 100%);
  --instagram-shadow: 0 4px 10px rgba(225, 48, 108, 0.10);
  --instagram-shadow-hover: 0 5px 12px rgba(225, 48, 108, 0.14);

  /* TikTok Official Token System */
  --tiktok-bg: #000000;
  /* TikTok Official Token System (Monochrome Dark + Subtle Brand Accents) */
  --tiktok-primary-gradient: linear-gradient(
    110deg,
    #080808 0%,
    #0a0d0e 30%,
    #155054 66%,
    #9b2948 100%
  );
  --tiktok-accent-cyan: #25F4EE;
  --tiktok-accent-red: #FE2C55;
  --tiktok-accent-soft: #FFF0F3;
  --tiktok-border: linear-gradient(135deg, rgba(37, 244, 238, 0.72) 0%, rgba(254, 44, 85, 0.72) 100%);
  --tiktok-shadow: -2px 3px 10px rgba(37, 244, 238, 0.07), 2px 3px 10px rgba(254, 44, 85, 0.07);
  --tiktok-shadow-hover: -3px 5px 14px rgba(37, 244, 238, 0.10), 3px 5px 14px rgba(254, 44, 85, 0.10);

  /* X / Twitter Official Token System (Monochrome Premium) */
  --x-black: #000000;
  --x-dark: #0F1419;
  --x-graphite: #1F2933;
  --x-gray: #536471;
  --x-border: rgba(15, 20, 25, 0.72);
  --x-border-strong: rgba(15, 20, 25, 0.82);
  --x-border-service: rgba(15, 20, 25, 0.55);
  --x-soft: rgba(15, 20, 25, 0.035);
  --x-white: #FFFFFF;
  --x-shadow: 0 4px 12px rgba(15, 20, 25, 0.06);
  --x-shadow-hover: 0 6px 16px rgba(15, 20, 25, 0.10);
  --x-cta-shadow: 0 4px 10px rgba(15, 20, 25, 0.10);
  --x-cta-shadow-hover: 0 5px 12px rgba(15, 20, 25, 0.14);

  /* YouTube Official Token System (Pure Red + White + Dark) */
  --youtube-primary: #FF0000;
  --youtube-primary-hover: #E60000;
  --youtube-dark: #0F0F0F;
  --youtube-secondary: #606060;
  --youtube-border: rgba(255, 0, 0, 0.58);
  --youtube-border-strong: rgba(255, 0, 0, 0.78);
  --youtube-border-service: rgba(255, 0, 0, 0.52);
  --youtube-soft-bg: rgba(255, 0, 0, 0.035);
  --youtube-soft-bg-hover: rgba(255, 0, 0, 0.055);
  --youtube-white: #FFFFFF;
  --youtube-shadow: 0 4px 12px rgba(255, 0, 0, 0.045);
  --youtube-shadow-hover: 0 6px 16px rgba(255, 0, 0, 0.075);
  --youtube-cta-shadow: 0 4px 10px rgba(255, 0, 0, 0.08);
  --youtube-cta-shadow-hover: 0 5px 13px rgba(255, 0, 0, 0.11);

  --background: #080B14;
  --background-secondary: #0D1120;
  --surface: #111728;
  --surface-elevated: #151D32;
  --foreground: #F8FAFF;
  
  --card: #111728;
  --card-foreground: #F8FAFF;
  --popover: #151D32;
  --popover-foreground: #F8FAFF;
  
  --primary: #FF4D6D;
  --primary-hover: #FF647F;
  --primary-foreground: #FFFFFF;
  
  --secondary: #111728;
  --secondary-foreground: #F8FAFF;
  
  --muted: #111728;
  --muted-foreground: #A8B1C7;
  
  --accent: #FFB84D;
  --accent-foreground: #F8FAFF;
  
  --destructive: oklch(0.396 0.141 25.723);
  --destructive-foreground: oklch(0.637 0.237 25.331);
  --success: #22D3A7;
  
  --border: #26314D;
  --input: #111728;
  --ring: #FF4D6D;
  
  --chart-1: #FF4D6D;
  --chart-2: #FFB84D;
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);
  --sidebar: #111728;
  --sidebar-foreground: #F8FAFF;
  --sidebar-primary: #FF4D6D;
  --sidebar-primary-foreground: #FFFFFF;
  --sidebar-accent: #151D32;
  --sidebar-accent-foreground: #F8FAFF;
  --sidebar-border: #26314D;
  --sidebar-ring: #FF4D6D;
  --radius: 0.5rem;
}

.cloutflow-admin {
  --admin-bg: #F7F9FA;
  --admin-sidebar: #071D26;
  --admin-sidebar-secondary: #0A2630;
  --admin-sidebar-border: #11313B;
  --admin-card: #FFFFFF;
  --admin-card-hover: #FBFCFC;
  --admin-border: #E3E8EA;
  --admin-divider: #EDF1F2;
  --admin-primary: #0F8F8A;
  --admin-primary-hover: #0B7A76;
  --admin-primary-soft: #E7F5F4;
  --admin-primary-border: #BFE5E2;
  --admin-text: #142126;
  --admin-text-secondary: #65737A;
  --admin-text-muted: #8A979D;
  --admin-success: #16B77A;
  --admin-warning: #F59E0B;
  --admin-danger: #EF4444;
  --admin-info: #169BD5;
  
  --background: var(--admin-bg);
  --foreground: var(--admin-text);
  --card: var(--admin-card);
  --card-foreground: var(--admin-text);
  --popover: var(--admin-card);
  --popover-foreground: var(--admin-text);
  --primary: var(--admin-primary);
  --primary-foreground: #FFFFFF;
  --secondary: var(--admin-primary-soft);
  --secondary-foreground: var(--admin-primary-hover);
  --muted: var(--admin-bg);
  --muted-foreground: var(--admin-text-muted);
  --accent: var(--admin-primary-soft);
  --accent-foreground: var(--admin-primary-hover);
  --destructive: var(--admin-danger);
  --destructive-foreground: #FFFFFF;
  --border: var(--admin-border);
  --input: var(--admin-border);
  --ring: var(--admin-primary);
}

.cloutflow-admin body {
  background-color: var(--admin-bg);
  color: var(--admin-text);
}

.dark {
