  --secondary-foreground: #F8FAFF;
  
  --muted: #111728;
  --muted-foreground: #A8B1C7;
  
  --accent: #FFB84D;
  --accent-foreground: #F8FAFF;
  
  --destructive: oklch(0.396 0.141 25.723);
  --destructive-foreground: oklch(0.637 0.237 25.331);
  --success: #22D3A7;
  
  --border: #26314D;
  --input: #111728;
