  --chart-1: #FF4D6D;
  --chart-2: #FFB84D;
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);
  --sidebar: #111728;
  --sidebar-foreground: #F8FAFF;
  --sidebar-primary: #FF4D6D;
  --sidebar-primary-foreground: #FFFFFF;
  --sidebar-accent: #151D32;
  --sidebar-accent-foreground: #F8FAFF;
  --sidebar-border: #26314D;
  --sidebar-ring: #FF4D6D;
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground font-sans;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }
  html {
    @apply font-sans;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }
}

@keyframes float {
  0% { transform: translateY(0px) rotate(0deg); }
  100% { transform: translateY(-8px) rotate(0.5deg); }
}

@keyframes slide-right {
  0% { transform: translateX(-100%); }
  50% { transform: translateX(500%); }
  100% { transform: translateX(500%); }
}

@keyframes slide-down {
  0% { transform: translateY(-100%); }
  50% { transform: translateY(500%); }
  100% { transform: translateY(500%); }
}


/* =========================================================
   CLOUTFLOW HOME V33 — rebuilt from the two approved refs
   Desktop: light lilac/white scene. Mobile: purple hero + white body.
   Everything is scoped to .cf-ref-home.
   ========================================================= */

.cf-ref-home {
  --cf-purple:#FF4D6D;
  --cf-purple-2:#FF647F;
  --cf-blue:#FFB84D;
  --cf-ink:#151744;
  --cf-text:#656b91;
  --cf-line:#F1D8D1;
  min-height:100vh;
  overflow-x:hidden;
  background:#fbfaff;
  color:var(--cf-ink);
}
.cf-ref-home * { box-sizing:border-box; }
.cf-ref-shell { width:min(1200px, calc(100% - 56px)); margin-inline:auto; }

/* ===== desktop hero ===== */
.cf-ref-hero {
  position:relative;
  min-height:430px;
  overflow:hidden;
  background:
    radial-gradient(circle at 50% 3%, rgba(150,117,255,.11), transparent 32%),
    linear-gradient(180deg,#fefcff 0%,#f9f6ff 100%);
}
.cf-ref-hero::before {
  content:""; position:absolute; left:-8%; top:-110px; width:46%; height:225px;
  background:linear-gradient(135deg,#FF8A72 0%,#FFD5C5 65%,rgba(234,225,255,.55) 100%);
  border-radius:0 0 55% 45%; transform:rotate(-5deg); opacity:.72;
}
.cf-ref-hero-inner { position:relative; z-index:4; text-align:center; padding-top:54px; }
.cf-ref-logo {
  font-size:33px; line-height:1; font-weight:900; letter-spacing:-1.5px;
  background:linear-gradient(90deg,#FF4D6D 0%,#FF7A5C 50%,#FFB84D 100%);
  -webkit-background-clip:text; background-clip:text; color:transparent;
}
.cf-ref-eyebrow {
  width:max-content; max-width:92%; margin:20px auto 20px; padding:8px 18px;
  border:1.5px solid #FFD3C8; border-radius:999px; background:rgba(255,255,255,.78);
  display:flex; gap:9px; align-items:center; color:#FF5B69; font-size:14px;
  box-shadow:0 7px 22px rgba(110,80,220,.05);
}
.cf-ref-title { margin:0; font-weight:900; letter-spacing:-3px; line-height:1.03; }
.cf-ref-title-main { display:block; color:#151744; font-size:clamp(45px,4.5vw,68px); }
.cf-ref-title-gradient {
  display:block; font-size:clamp(45px,4.5vw,68px); margin-top:5px;
  background:linear-gradient(90deg,#FF4D6D 0%,#FF795C 48%,#FFB84D 100%);
  -webkit-background-clip:text; background-clip:text; color:transparent;
}
.cf-ref-subtitle { margin:24px auto 0; max-width:760px; font-size:19px; color:#676b8d; line-height:1.5; }

.cf-ref-hero-decor,.cf-ref-dots,.cf-ref-ring,.cf-ref-triangle,.cf-ref-bars { position:absolute; z-index:2; pointer-events:none; }
.cf-ref-heart {
  top:72px; left:10.5%; width:130px; height:103px; border-radius:24px;
  display:grid; place-items:center; color:white; transform:rotate(-9deg);
  background:linear-gradient(145deg,#8462f2 0%,#b6a3f9 100%);
  box-shadow:0 18px 36px rgba(94,72,205,.2);
}
.cf-ref-heart::after { content:""; position:absolute; bottom:-17px; left:34px; width:28px; height:28px; background:#8c6bf3; clip-path:polygon(0 0,100% 0,22% 100%); }
.cf-ref-dots { width:80px; height:55px; opacity:.62; background-image:radial-gradient(circle,#c9b9f5 2px,transparent 2.6px); background-size:14px 14px; }
.cf-ref-dots-left { left:5%; top:250px; }
.cf-ref-dots-right { right:8%; top:42px; }
.cf-ref-ring { width:28px; height:28px; border:4px solid #cbbcf3; border-radius:50%; opacity:.72; }
.cf-ref-ring-left { left:18%; top:292px; }
.cf-ref-ring-right { right:19%; top:130px; }
.cf-ref-triangle { left:17%; top:294px; width:23px; height:23px; border:4px solid #cabaf4; clip-path:polygon(50% 0,100% 100%,0 100%); opacity:.7; }
.cf-ref-bars { right:8.5%; top:150px; width:150px; height:150px; display:flex; align-items:flex-end; gap:10px; }
.cf-ref-bars span { width:23px; border-radius:7px 7px 2px 2px; background:linear-gradient(180deg,#c8b9ff 0%,#7f63f2 100%); box-shadow:0 12px 22px rgba(100,75,208,.16); }
.cf-ref-bars span:nth-child(1){height:44px}.cf-ref-bars span:nth-child(2){height:67px}.cf-ref-bars span:nth-child(3){height:92px}.cf-ref-bars span:nth-child(4){height:116px}
.cf-ref-bars b { position:absolute; right:-4px; top:-34px; color:#a691f7; font-size:78px; font-weight:300; transform:rotate(-7deg); }

.cf-ref-wave { position:absolute; z-index:3; left:-4%; right:-4%; bottom:-49px; height:112px; background:#fbfaff; border-radius:52% 48% 0 0 / 44% 46% 0 0; transform:rotate(-.7deg); }
.cf-ref-wave::before { content:""; position:absolute; left:-3%; right:-3%; top:-22px; height:52px; background:linear-gradient(90deg,#e4d4ff 0%,#d9c9ff 48%,#efe8ff 100%); border-radius:50%; opacity:.82; transform:rotate(1deg); }

/* ===== desktop body ===== */
.cf-ref-body { position:relative; min-height:560px; padding:34px 0 30px; background:#fbfaff; }
.cf-ref-section-title { text-align:center; margin-bottom:25px; }
.cf-ref-section-title h2 { margin:0; font-size:29px; line-height:1.15; font-weight:900; letter-spacing:-1px; color:#171943; }
.cf-ref-section-title p { margin:9px 0 0; font-size:15px; color:#6a6f91; }
.cf-ref-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:22px; max-width:900px; margin:0 auto; }
.cf-ref-platform-card {
  min-height:228px; padding:24px 20px 22px; text-decoration:none; color:#151744;
  background:rgba(255,255,255,.88); border:1px solid #e3def4; border-radius:22px;
  box-shadow:0 16px 34px rgba(73,56,144,.075); display:flex; flex-direction:column; align-items:center; justify-content:center;
  transition:transform .2s ease, box-shadow .2s ease;
}
.cf-ref-platform-card:hover { transform:translateY(-4px); box-shadow:0 20px 40px rgba(80,61,154,.12); }
.cf-ref-platform-icon { position:relative; width:92px; height:92px; margin-bottom:17px; filter:drop-shadow(0 10px 12px rgba(64,46,130,.12)); }
.cf-ref-platform-card h3 { margin:0; font-size:20px; line-height:1.1; font-weight:900; letter-spacing:-.5px; }
.cf-ref-platform-card > span { margin-top:11px; display:flex; align-items:center; gap:6px; font-size:14px; color:#764df2; }
.cf-ref-metrics { max-width:900px; margin:26px auto 0; padding:15px 20px; display:grid; grid-template-columns:repeat(3,1fr); border:1px solid #ddd8f2; border-radius:22px; background:rgba(255,255,255,.78); box-shadow:0 15px 28px rgba(76,56,145,.05); }
.cf-ref-metric { min-height:92px; position:relative; display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center; }
.cf-ref-metric-icon { width:25px; height:25px; color:#7147ed; margin-bottom:5px; stroke-width:2.2; }
.cf-ref-metric strong { font-size:28px; line-height:1; color:#7550ee; font-weight:900; }
.cf-ref-metric span { margin-top:7px; font-size:13px; color:#676d90; }
.cf-ref-metric i { position:absolute; right:0; top:12px; bottom:12px; width:1px; background:#ddd8f0; }
.cf-ref-trust { margin:19px auto 0; display:flex; justify-content:center; align-items:center; gap:20px; color:#383e68; font-size:14px; }
.cf-ref-trust span { display:flex; align-items:center; gap:7px; }.cf-ref-trust span svg{color:#754df0}.cf-ref-trust b{color:#9d94be}
.cf-ref-bottom-clouds { position:absolute; left:-65px; bottom:-85px; width:250px; height:145px; opacity:.75; background:radial-gradient(circle at 65% 25%,#eadfff 0 24%,transparent 25%),radial-gradient(circle at 42% 45%,#e0d0ff 0 31%,transparent 32%),radial-gradient(circle at 15% 55%,#eee2ff 0 28%,transparent 29%); }
.cf-ref-bottom-orbit { position:absolute; right:-75px; bottom:-98px; width:235px; height:235px; border:2px dashed #d8ccfa; border-radius:50%; opacity:.55; }

/* ===== mobile, matched to the approved screenshot ===== */
