  z-index: 0;
}

/* Base ambient tint ultra-suave (predominantemente branco + ice blue) */
.cf-bg-subtle-tint {
  position: absolute;
  inset: 0;
  background: radial-gradient(
    circle at 50% 18%,
    rgba(239, 246, 255, 0.55) 0%,
    rgba(248, 250, 252, 0.25) 55%,
    transparent 100%
  );
  z-index: 0;
}

/* 5. Glow Central: nasce atrás de "Grow your audience. Get noticed faster." e se expande suavemente para baixo */
.cf-bg-center-glow {
  position: absolute;
  top: 50px;
  left: 50%;
  transform: translateX(-50%);
  width: 860px;
  max-width: 95vw;
  height: 480px;
  background: radial-gradient(
    ellipse at 50% 30%,
    rgba(37, 99, 235, 0.065) 0%,
    rgba(59, 130, 246, 0.038) 35%,
    rgba(147, 197, 253, 0.015) 65%,
    transparent 80%
  );
  filter: blur(40px);
  pointer-events: none;
  z-index: 1;
}

/* 7. Soft Glow atrás do conjunto dos quatro cards */
.cf-bg-cards-glow {
  position: absolute;
  top: 320px;
  left: 50%;
  transform: translateX(-50%);
  width: 960px;
  max-width: 96vw;
  height: 380px;
  background: radial-gradient(
    ellipse at 50% 50%,
    rgba(239, 246, 255, 0.8) 0%,
    rgba(219, 234, 254, 0.25) 45%,
    rgba(241, 245, 249, 0.08) 70%,
    transparent 90%
  );
  filter: blur(35px);
  pointer-events: none;
  z-index: 1;
}

/* LEVEL 1: SVG Arcs and Flow Lines Layer */
.cf-bg-arcs-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 1;
}

/* ==========================================================
   LEVEL 3: METRIC BUBBLES (8.4K, 2.7K, 1.3K, 12.5K)
   - Fundo branco levemente translúcido
   - Borda azul muito clara + pill arredondado
   - Ícone e números azuis
   - Sombra azul extremamente suave + halo branco sutil
   ========================================================== */
.cf-metric-bubble {
  position: absolute;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4.5px 11px;
  background: rgba(255, 255, 255, 0.88);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  border: 1px solid rgba(191, 219, 254, 0.8);
  border-radius: 9999px;
  font-size: 11.5px;
  font-weight: 650;
  color: #1d4ed8;
  letter-spacing: -0.2px;
  pointer-events: none;
  user-select: none;
  box-shadow: 0 4px 14px rgba(37, 99, 235, 0.05), 0 0 16px rgba(255, 255, 255, 0.9);
  z-index: 3;
}

.cf-metric-bubble svg {
  width: 13px;
  height: 13px;
  stroke-width: 2;
  color: #2563eb;
  opacity: 0.9;
}

/* Bubble positions (com pequenas variações verticais como na referência) */
.cf-bubble-followers {
  top: 108px;
  left: max(28px, calc(50% - 460px));
}

.cf-bubble-likes {
  top: 68px;
  left: max(160px, calc(50% - 250px));
}

.cf-bubble-comments {
  top: 74px;
  right: max(160px, calc(50% - 250px));
}

.cf-bubble-views {
  top: 114px;
  right: max(28px, calc(50% - 460px));
}

/* ==========================================================
   LEVEL 2: SOCIAL ENGAGEMENT OUTLINE ICONS
   - Azul muito claro, stroke fino, baixa opacidade
   - Sem logos de plataformas ou círculos sólidos
   ========================================================== */
.cf-social-action-icon {
  position: absolute;
  pointer-events: none;
  user-select: none;
  color: #3b82f6;
  opacity: 0.22;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
}

.cf-action-heart-left {
  top: 160px;
  left: max(35px, calc(50% - 420px));
}

.cf-action-play-right {
  top: 175px;
  right: max(40px, calc(50% - 430px));
}

.cf-action-eye-left {
  top: 245px;
  left: max(20px, calc(50% - 540px));
}

.cf-action-user-right {
  top: 255px;
  right: max(20px, calc(50% - 540px));
}

.cf-action-comment-bottom-left {
  bottom: 150px;
  left: max(30px, calc(50% - 510px));
}

.cf-action-users-bottom-right {
  bottom: 140px;
  right: max(35px, calc(50% - 510px));
}

/* ==========================================================
   LEVEL 3 & 2: SPARKLES & MICRO PONTOS LUMINOSOS
   - Mix de ✦, ✧, •
   - Principais com pequeno halo luminoso difuso
   ========================================================== */
.cf-sparkle {
  position: absolute;
  pointer-events: none;
  color: #2563eb;
  user-select: none;
  line-height: 1;
  font-family: inherit;
  z-index: 2;
}

/* Sparkles principais com halo luminoso (Drop-shadow + soft radial glow) */
.cf-sparkle-main {
  color: #1d4ed8;
  filter: drop-shadow(0 0 6px rgba(59, 130, 246, 0.45));
  z-index: 3;
}

.cf-sp-1 { top: 88px; left: calc(50% - 350px); font-size: 15px; opacity: 0.45; }
.cf-sp-2 { top: 135px; right: calc(50% - 340px); font-size: 14px; opacity: 0.42; }
.cf-sp-3 { top: 215px; left: calc(50% - 170px); font-size: 13px; opacity: 0.38; }
.cf-sp-4 { bottom: 170px; right: calc(50% - 460px); font-size: 14px; opacity: 0.40; }

/* Sparkles secundários */
.cf-sp-5 { top: 60px; left: calc(50% + 80px); font-size: 11px; opacity: 0.28; }
.cf-sp-6 { top: 120px; left: calc(50% - 190px); font-size: 12px; opacity: 0.26; }
.cf-sp-7 { top: 210px; right: calc(50% - 160px); font-size: 11px; opacity: 0.30; }
.cf-sp-8 { top: 260px; left: calc(50% - 470px); font-size: 13px; opacity: 0.24; }
.cf-sp-9 { top: 275px; right: calc(50% - 460px); font-size: 11px; opacity: 0.26; }
.cf-sp-10 { bottom: 195px; left: calc(50% - 440px); font-size: 13px; opacity: 0.25; }
.cf-sp-11 { bottom: 95px; left: calc(50% + 280px); font-size: 12px; opacity: 0.28; }
.cf-sp-12 { bottom: 80px; left: calc(50% - 290px); font-size: 11px; opacity: 0.22; }

/* Micro pontos luminosos (•) */
.cf-sparkle-dot {
  position: absolute;
  pointer-events: none;
  user-select: none;
  color: #3b82f6;
  line-height: 1;
  z-index: 2;
}

.cf-dot-pt-1 { top: 95px; right: calc(50% - 110px); font-size: 10px; opacity: 0.32; }
.cf-dot-pt-2 { top: 165px; left: calc(50% - 310px); font-size: 9px; opacity: 0.28; }
.cf-dot-pt-3 { bottom: 230px; right: calc(50% - 380px); font-size: 10px; opacity: 0.25; }
.cf-dot-pt-4 { bottom: 120px; left: calc(50% - 360px); font-size: 9px; opacity: 0.22; }

/* ==========================================================
   LEVEL 2: DOT CLOUDS LATERAIS COM FADE PROGRESSIVO
   - Mistura de micro/pequenos/médios dots
   - Mais densos nas extremidades, desaparecendo em direção ao centro
   - Não retangular (máscara radial orgânica)
   ========================================================== */
.cf-dot-cloud {
  position: absolute;
  pointer-events: none;
  background-image: 
    radial-gradient(rgba(37, 99, 235, 0.26) 1.2px, transparent 1.2px),
    radial-gradient(rgba(59, 130, 246, 0.18) 0.8px, transparent 0.8px);
  background-size: 15px 15px, 23px 23px;
  background-position: 0 0, 7px 7px;
  z-index: 2;
}

.cf-dot-cloud-left {
  bottom: 25px;
  left: 15px;
  width: 240px;
  height: 170px;
  opacity: 0.42;
  mask-image: radial-gradient(ellipse at 15% 85%, black 20%, rgba(0, 0, 0, 0.4) 50%, transparent 80%);
  -webkit-mask-image: radial-gradient(ellipse at 15% 85%, black 20%, rgba(0, 0, 0, 0.4) 50%, transparent 80%);
}

.cf-dot-cloud-right {
  bottom: 30px;
  right: 15px;
  width: 250px;
  height: 180px;
  opacity: 0.40;
  mask-image: radial-gradient(ellipse at 85% 85%, black 20%, rgba(0, 0, 0, 0.4) 50%, transparent 80%);
  -webkit-mask-image: radial-gradient(ellipse at 85% 85%, black 20%, rgba(0, 0, 0, 0.4) 50%, transparent 80%);
}

/* ==========================================================
   RESPONSIVIDADE E ADAPTAÇÕES VIEWPORT (ETAPA 3)
   - Desktop grande (1920x1080, 1536x864): expansão total sem corte ou limitação de container
   - Desktop compacto/baixo (1440x900, 1366x768, 1280x720): zero scroll horizontal e vertical equilibrado
   - Mobile refinado (360x800, 375x812, 390x844, 393x852, 430x932):
     * 2 metric bubbles (8.4K e 2.7K)
     * 4-8 sparkles refinados
     * Arcos Bézier verticais e limpos
     * Dot cloud discreta sem obstrução
     * Prioridade total para leitura e cards 2x2
   ========================================================== */
@media (min-width: 1441px) {
  .cf-bubble-followers { left: max(40px, calc(50% - 580px)); }
  .cf-bubble-views { right: max(40px, calc(50% - 580px)); }
