  transition:transform 180ms ease!important;
}
.cf-v68-card-primary::after{
  content:"";
  position:absolute;
  top:-40%;
  left:-35%;
  width:22%;
  height:180%;
  background:rgba(255,255,255,.24);
  transform:rotate(18deg);
  opacity:0;
  pointer-events:none;
  transition:left 420ms ease,opacity 180ms ease;
}
@media (hover:hover) and (pointer:fine){
