    transform:translate(3px,-1px)!important;
  }
  .cf-v68-card-primary:hover::after{
    left:115%;
    opacity:1;
  }
}
.cf-v68-card-primary:active{
  transform:scale(.98)!important;
  transition-duration:80ms!important;
}
