/* V268 — Structural builder layout fix.
   The two workflow columns are independent surfaces. The shared wrapper no longer
   paints a full-height white box, so a compact Ready/Analyzing card does not leave
   a false empty panel beside the taller controls column. */
@media (min-width:901px){
  .cf-premium-builder{
    width:min(100%,1000px);
    margin:24px auto 26px;
    padding:0;
    border:0;
    border-radius:0;
    background:transparent;
    box-shadow:none;
  }
  .cf-premium-builder-head{
    width:100%;
    margin:0 0 18px;
    padding:23px 18px 18px;
    border:1px solid #e3e8f1;
    border-radius:22px;
    background:rgba(255,255,255,.94);
    box-shadow:0 18px 45px rgba(43,51,82,.055);
  }
  .cf-premium-builder-grid{
    display:grid;
    grid-template-columns:minmax(0,.92fr) minmax(0,1.08fr);
    gap:16px;
    align-items:start;
  }
  .cf-premium-builder-controls,
  .cf-premium-builder-result{
    align-self:start;
    height:auto;
    min-height:0;
    box-shadow:0 14px 34px rgba(43,51,82,.045);
  }
  .cf-premium-builder-result{
    position:relative;
    padding:0 12px 12px;
  }
  .cf-pb-result-idle .cf-pb-empty{
    min-height:112px;
    padding:14px 28px 16px;
  }
  .cf-pb-result-idle .cf-pb-empty>span{
    width:40px;
    height:40px;
    border-radius:13px;
    font-size:18px;
  }
  .cf-pb-result-idle .cf-pb-empty h3{margin:8px 0 3px}
  .cf-pb-result-idle .cf-pb-summary{margin-bottom:7px}

  /* Keep the left flow compact without changing its hierarchy or controls. */
  .cf-premium-builder-controls .cf-pb-step{padding-top:13px;padding-bottom:13px}
  .cf-premium-builder-controls .cf-pb-label{margin-bottom:9px}
  .cf-premium-builder-controls .cf-pb-platforms{margin-bottom:10px}
  .cf-premium-builder-controls .cf-pb-privacy{margin-top:6px}

  /* Result previews retain their mobile source dimensions and never fill/stretch the card. */
  .cf-pb-native-stage{min-height:0;height:auto;align-items:flex-start}
  .cf-pb-native-mobile{width:430px;max-width:100%;height:auto;flex:0 0 auto}
}

