/* V273 — true 2.5D service icon system, matched to the plan-card visual language.
   The symbol is flat/graphic with a single offset depth layer — not glossy 3D. */
.cf-pb-service-icon,
.cf-pb-platform-icon{
  position:relative;
  display:inline-grid;
  place-items:center;
  flex:none;
}
.cf-pb-service-icon{
  width:36px;
  height:36px;
  border-radius:11px;
  background:linear-gradient(145deg,#fff 0%,var(--pb-icon-soft) 100%);
  border:1px solid color-mix(in srgb,var(--pb-icon-main) 9%,#fff 91%);
  box-shadow:0 0px 0px color-mix(in srgb,var(--pb-icon-main) 13%,transparent),inset 0 1px 0 rgba(255,255,255,.96);
  overflow:hidden;
}
.cf-pb-service-icon:after{
  content:"";
  position:absolute;
  width:22px;
  height:8px;
  left:50%;
  bottom:3px;
  translate:-50% 0;
  border-radius:50%;
  background:color-mix(in srgb,var(--pb-icon-main) 12%,transparent);
  filter:blur(4px);
  pointer-events:none;
}
.cf-pb-service-icon.is-compact{width:31px;height:31px;border-radius:9px}
.cf-pb-glyph{position:relative;z-index:1;width:23px!important;height:23px!important;overflow:visible}
.cf-pb-service-icon.is-compact .cf-pb-glyph{width:19px!important;height:19px!important}
.cf-pb-glyph .main{fill:var(--pb-icon-main)}
.cf-pb-glyph .alt{fill:var(--pb-icon-alt)}
.cf-pb-glyph .soft{fill:#fff;stroke:var(--pb-icon-main);stroke-width:1.8}
.cf-pb-glyph .depth{fill:color-mix(in srgb,var(--pb-icon-main) 48%,#381162 52%);opacity:.36}
.cf-pb-glyph .depth.alt{fill:color-mix(in srgb,var(--pb-icon-alt) 50%,#24133d 50%);opacity:.34}
.cf-pb-glyph .shine{fill:none;stroke:rgba(255,255,255,.72);stroke-width:1.5;stroke-linecap:round}
.cf-pb-glyph .main-line{fill:none;stroke:var(--pb-icon-main);stroke-width:2.15;stroke-linecap:round;stroke-linejoin:round}
.cf-pb-glyph-bars .depth{opacity:.28}
.cf-pb-glyph-setup .main{opacity:.82}

