    transform: translateY(0) scale(1) !important;
    transition:
      transform .28s cubic-bezier(.2,.8,.2,1),
      box-shadow .28s ease,
      border-color .28s ease,
      filter .28s ease !important;
    will-change: transform, box-shadow !important;
  }

  .cf-plans-pricing .cf-plans-card:hover {
    z-index: 30 !important;
    transform: translateY(-14px) scale(1.045) !important;
    filter: saturate(1.10) brightness(1.015) !important;
    box-shadow:
      0 34px 64px rgba(38, 31, 82, .22),
      0 16px 32px rgba(116, 61, 255, .14),
      0 0 0 2px rgba(133, 69, 255, .20) !important;
  }

  .cf-plans-pricing .cf-plans-card::before {
    content: "" !important;
    position: absolute !important;
    inset: -7px !important;
    z-index: -1 !important;
    border-radius: calc(1em + 12px) !important;
    pointer-events: none !important;
    opacity: 0 !important;
    background:
      linear-gradient(135deg,
        rgba(255,45,105,.24),
        rgba(183,49,221,.18) 48%,
        rgba(102,55,255,.25)
      ) !important;
    filter: blur(14px) !important;
    transform: scale(.96) !important;
    transition: opacity .25s ease, transform .28s ease !important;
  }

  .cf-plans-pricing .cf-plans-card:hover::before {
    opacity: .78 !important;
    transform: scale(1.025) !important;
