/* ==========================================================================
   V350 — STRONG RESPONSIVE PRICING CTA
   Makes every pricing-card CTA clearly react to mouse/touch interaction.
   ========================================================================== */

.cf-plans-card-cta {
  position: relative !important;
  overflow: hidden !important;
  isolation: isolate !important;
  transition:
    transform .22s cubic-bezier(.22,.8,.28,1),
    box-shadow .22s ease,
    filter .22s ease !important;
  will-change: transform !important;
}

.cf-plans-card-cta::before {
  content: "" !important;
  position: absolute !important;
  top: -30% !important;
  bottom: -30% !important;
  left: -38% !important;
  width: 34% !important;
  z-index: -1 !important;
  pointer-events: none !important;
  background: linear-gradient(
    105deg,
    transparent 0%,
    rgba(255,255,255,.18) 26%,
    rgba(255,255,255,.72) 50%,
    rgba(255,255,255,.18) 74%,
    transparent 100%
  ) !important;
  transform: skewX(-18deg) !important;
  opacity: 0 !important;
}

@media (hover: hover) and (pointer: fine) {
  .cf-plans-card-cta:hover {
    transform: translateY(-5px) scale(1.035) !important;
    filter: brightness(1.07) saturate(1.10) !important;
    box-shadow:
      0 16px 32px rgba(46, 35, 105, .24),
      0 7px 16px rgba(255, 45, 105, .15),
      0 0 0 2px rgba(255,255,255,.32) inset !important;
  }

  .cf-plans-card-cta:hover::before {
    opacity: 1 !important;
    animation: cfPlanCtaShine .62s cubic-bezier(.22,.8,.28,1) both !important;
  }

  .cf-plans-card-cta:active {
    transform: translateY(-1px) scale(.985) !important;
    box-shadow:
      0 7px 16px rgba(46, 35, 105, .18),
      0 2px 7px rgba(255, 45, 105, .10) !important;
  }
}

@keyframes cfPlanCtaShine {
  from { left: -38%; }
  to { left: 112%; }
}

/* Strong keyboard/focus feedback too. */
.cf-plans-card-cta:focus-visible {
  outline: none !important;
  transform: translateY(-4px) scale(1.025) !important;
  box-shadow:
    0 0 0 3px rgba(255,255,255,.95),
    0 0 0 6px rgba(120,61,255,.34),
    0 14px 28px rgba(46,35,105,.20) !important;
}

/* Mobile/touch: immediate press feedback instead of hover-only behavior. */
@media (hover: none), (pointer: coarse) {
  .cf-plans-card-cta {
    min-height: 48px !important;
    -webkit-tap-highlight-color: transparent !important;
    touch-action: manipulation !important;
  }

  .cf-plans-card-cta:active {
    transform: scale(.965) !important;
    filter: brightness(.96) saturate(1.06) !important;
    box-shadow:
      0 5px 12px rgba(46,35,105,.16),
      inset 0 2px 5px rgba(0,0,0,.08) !important;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cf-plans-card-cta,
  .cf-plans-card-cta::before {
    transition: none !important;
    animation: none !important;
  }
}

