/* ==========================================================================
   V392 — OFFER REBUILD: TRUE 3-PAGE FUNNEL
   Page 1 Profile Builder · Page 2 Package · Page 3 Checkout
   Home-inspired visual language: pink/purple gradients, soft background,
   compact builder cards, network icons, premium pills and restrained shadows.
   ========================================================================== */

.cf-offer-page {
  background:
    radial-gradient(ellipse 540px 280px at 1% 46%, rgba(255,45,114,.055), transparent 72%),
    radial-gradient(ellipse 540px 280px at 99% 50%, rgba(116,61,255,.055), transparent 72%),
    linear-gradient(180deg,#ffffff 0%,#fcfdff 55%,#ffffff 100%) !important;
}

.cf-offer-main {
  max-width:1000px !important;
}

.cf-offer-hub {
  width:100%;
  animation:cfOfferIn .34s ease both;
}

.cf-offer-hub-head {
  max-width:720px;
  margin:0 auto 15px;
  text-align:center;
}
.cf-offer-hub-head > span {
  display:inline-flex;
  align-items:center;
  gap:5px;
  color:#ff2d72;
  font-size:9px;
  line-height:1;
  font-weight:850;
  letter-spacing:.085em;
}
.cf-offer-hub-head > span svg { width:12px;height:12px; }
.cf-offer-hub-head h1 {
  margin:7px 0 0;
  color:#11192c;
  font-size:30px;
  line-height:1.05 !important;
  font-weight:880;
  letter-spacing:-.05em !important;
}
.cf-offer-hub-head h1 em {
  font-style:normal;
  background:linear-gradient(90deg,#ff2d72 0%,#d832cf 48%,#743dff 100%);
  -webkit-background-clip:text;
  background-clip:text;
  color:transparent;
}
.cf-offer-hub-head p {
