}
.cf-offer-result-summary > span { min-width:0;display:flex;flex-direction:column; }
.cf-offer-result-summary small { color:#8a96a9;font-size:7px;font-weight:720;text-transform:uppercase;letter-spacing:.04em; }
.cf-offer-result-summary strong { overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:1px;color:#182238;font-size:9.5px; }
.cf-offer-result-summary > svg { width:12px;height:12px;color:#23b889; }

.cf-offer-hub-loader {
