}
.cf-offer-hub-trustline svg { width:10px;height:10px;color:#7b4cff; }

/* Page 2: package stage becomes a polished Home-style section */
.cf-offer-packages-stage {
  max-width:940px;
  margin:0 auto;
}
.cf-offer-packages-head {
  align-items:end !important;
}
.cf-offer-packages-head h1 em {
  background:linear-gradient(90deg,#ff2d72,#743dff);
  -webkit-background-clip:text;background-clip:text;color:transparent;
}
.cf-offer-plan-grid {
  gap:11px !important;
}
.cf-offer-plan-card {
  background:linear-gradient(180deg,#fff,#fcfdff) !important;
  border-radius:18px !important;
  box-shadow:0 10px 24px rgba(28,38,70,.04) !important;
}
.cf-offer-plan-card.is-selected {
  box-shadow:0 16px 32px color-mix(in srgb,var(--offer-accent) 15%,transparent) !important;
}
.cf-offer-plan-cta {
  border-radius:10px !important;
}

/* Page 3: centered premium checkout */
.cf-offer-review-stage {
  max-width:860px;
  margin:0 auto;
  grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr) !important;
  gap:32px !important;
}
.cf-offer-review-stage .cf-offer-copy h1 em {
  background:linear-gradient(90deg,#ff2d72,#743dff);
  -webkit-background-clip:text;background-clip:text;color:transparent;
}
.cf-offer-checkout-card {
  border-radius:20px !important;
  box-shadow:0 16px 40px rgba(31,40,72,.07) !important;
}

/* The permanent trust bar is intentionally understated because the
   Profile builder already carries trust cues like the public Home. */
.cf-offer-trustbar {
  max-width:860px !important;
  min-height:42px !important;
  margin-bottom:7px !important;
  border-radius:12px !important;
  box-shadow:none !important;
  background:rgba(255,255,255,.66) !important;
}

@media (max-width:900px) {
  .cf-offer-main { padding:16px 12px 14px !important; }
  .cf-offer-hub-head { margin-bottom:11px; }
  .cf-offer-hub-head h1 { font-size:24px !important; }
  .cf-offer-hub-head p { font-size:9.5px; }

  .cf-offer-builder-grid { grid-template-columns:1fr;gap:9px;max-width:540px; }
  .cf-offer-builder-controls { padding:12px; }
  .cf-offer-builder-result { padding:10px; }
  .cf-offer-builder-scene { min-height:155px;padding:13px 10px; }
  .cf-offer-builder-result-top { padding-bottom:7px; }
  .cf-offer-hub-steps { padding-top:7px; }

  .cf-offer-hub-networks button { height:47px;font-size:7px; }
  .cf-offer-main-cta { min-height:42px;font-size:10.5px; }

  .cf-offer-hub-trustline { margin-top:8px;gap:6px; }

  .cf-offer-review-stage {
    grid-template-columns:1fr !important;
    gap:16px !important;
    max-width:540px;
  }
  .cf-offer-review-stage .cf-offer-copy { text-align:center; }

  .cf-offer-packages-stage { max-width:560px; }
}

@media (max-width:520px) {
  .cf-offer-hub-head h1 { font-size:22px !important; }
  .cf-offer-hub-head p { max-width:340px; }
  .cf-offer-builder-grid { width:100%; }
  .cf-offer-hub-networks { gap:4px; }
  .cf-offer-hub-networks button { height:45px;padding:2px; }
  .cf-offer-hub-networks button img { width:18px!important;height:18px!important; }
  .cf-offer-hub-steps small { display:none; }
  .cf-offer-hub-steps > div { justify-content:center; }
  .cf-offer-hub-steps span { text-align:center; }
  .cf-offer-hub-trustline span { font-size:7px; }
}

