/* V443 DESKTOP — interactive goal/network/profile/analyze controls */
@media (min-width: 901px) {
  html body .cf-o10-goal-builder button {
    pointer-events: auto !important;
    cursor: pointer !important;
    user-select: none !important;
    touch-action: manipulation !important;
  }

  html body .cf-o10-gb-goal-card,
  html body .cf-o10-gb-network,
  html body .cf-o10-gb-linked-input,
  html body .cf-o10-gb-unlink,
  html body .cf-o10-gb-analyze {
    position: relative !important;
    transition:
      transform .18s ease,
      box-shadow .18s ease,
      border-color .18s ease,
      background-color .18s ease,
      color .18s ease,
      filter .18s ease !important;
  }

  html body .cf-o10-gb-goal-card:hover,
  html body .cf-o10-gb-network:hover {
    transform: translateY(-2px) !important;
    border-color: rgba(196, 54, 213, .42) !important;
    box-shadow: 0 7px 18px rgba(89, 61, 145, .10) !important;
  }

  html body .cf-o10-gb-goal-card:active,
  html body .cf-o10-gb-network:active,
  html body .cf-o10-gb-linked-input:active,
  html body .cf-o10-gb-unlink:active,
  html body .cf-o10-gb-analyze:active {
    transform: translateY(0) scale(.975) !important;
  }

  html body .cf-o10-gb-goal-card.is-active,
  html body .cf-o10-gb-network.is-active {
    box-shadow: 0 6px 16px rgba(222, 42, 137, .10) !important;
  }

  html body .cf-o10-gb-goal-card:focus-visible,
  html body .cf-o10-gb-network:focus-visible,
  html body .cf-o10-gb-linked-input:focus-visible,
  html body .cf-o10-gb-unlink:focus-visible,
  html body .cf-o10-gb-analyze:focus-visible {
    outline: 2px solid rgba(137, 55, 255, .42) !important;
    outline-offset: 3px !important;
  }

  html body .cf-o10-gb-linked-input:hover {
    border-color: #ccb8ff !important;
    background: #fcfaff !important;
    box-shadow: 0 5px 14px rgba(123, 53, 255, .08) !important;
  }

  html body .cf-o10-gb-unlink:hover {
    color: #ec2f73 !important;
    border-color: #ffc0d5 !important;
    background: #fff8fb !important;
    box-shadow: 0 5px 14px rgba(255, 45, 114, .08) !important;
  }

  html body .cf-o10-gb-analyze:hover {
    transform: translateY(-2px) !important;
    filter: brightness(1.055) saturate(1.05) !important;
    box-shadow: 0 13px 28px rgba(178, 46, 224, .25) !important;
  }

  html body .cf-o10-gb-analyze svg {
    transition: transform .18s ease !important;
  }

  html body .cf-o10-gb-analyze:hover svg {
    transform: scale(1.08) !important;
  }

  html body .cf-o10-gb-check {
    animation: cf-o10-select-pop .22s cubic-bezier(.2,.8,.3,1) both !important;
  }
}

@keyframes cf-o10-select-pop {
  0% { transform: scale(.65); opacity: 0; }
  70% { transform: scale(1.12); opacity: 1; }
  100% { transform: scale(1); opacity: 1; }
}


/* V445 DESKTOP — preserve goal icon artwork; recolor it dynamically by selected network.
   Instagram = pink/purple, TikTok = cyan/red, YouTube = red, X = graphite/black. */
@media (min-width: 901px) {
  html body .cf-o10-goal-builder .cf-o10-gb-goal-icon {
    transition: filter .22s ease, background .22s ease, box-shadow .22s ease !important;
  }

  /* Instagram */
  html body .cf-o10-goal-builder[data-network="instagram"] .cf-o10-gb-goal-icon {
    filter: none !important;
  }

  /* TikTok — cyan + hot-pink/red character while keeping the original icon shape */
  html body .cf-o10-goal-builder[data-network="tiktok"] .cf-o10-gb-goal-icon {
    filter: hue-rotate(115deg) saturate(1.35) brightness(1.04) !important;
    background: linear-gradient(135deg, rgba(37,244,238,.10), rgba(254,44,85,.07)) !important;
  }

  /* YouTube — red */
  html body .cf-o10-goal-builder[data-network="youtube"] .cf-o10-gb-goal-icon {
    filter: hue-rotate(318deg) saturate(2.15) brightness(1.06) !important;
    background: rgba(255,0,0,.055) !important;
  }

  /* X / Twitter — graphite black */
  html body .cf-o10-goal-builder[data-network="twitter"] .cf-o10-gb-goal-icon,
  html body .cf-o10-goal-builder[data-network="x"] .cf-o10-gb-goal-icon {
    filter: grayscale(1) saturate(0) brightness(.50) contrast(1.38) !important;
    background: rgba(17,24,39,.045) !important;
  }
}


