  62%  { transform: rotate(180deg) scale(1); }
  70%  { transform: rotate(185deg) scale(1.025); }
  78%  { transform: rotate(360deg) scale(1.035); }
  90%  { transform: rotate(360deg) scale(1); }
  100% { transform: rotate(360deg) scale(1); }
}

